import {createDraftStore} from './draft-store.js';
const paths={cube:'<path d="m12 3 9 5v9l-9 5-9-5V8z"/><path d="m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',back:'<path d="M20 12H5m5-5-5 5 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',receipt:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2zM9 7h6M9 11h6M9 15h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3M12 14v3"/>',help:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M20 16v3a2 2 0 0 1-2 2h-4"/><rect x="2" y="11" width="4" height="7" rx="2"/><rect x="18" y="11" width="4" height="7" rx="2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',wallet:'<path d="M3 7V5a2 2 0 0 1 2-2h13v4M3 7h18v14H3zM21 12h-6v4h6"/>',logout:'<path d="M9 3H3v18h6m1-9h11m-4-4 4 4-4 4"/>',edit:'<path d="m16 3 5 5L8 21H3v-5zM13 6l5 5"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=n=>n?new Date(n).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const byteSize=n=>n>1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`;
const statusLabels={pending:'待审核',approved:'已通过',needs_info:'待补充',paid:'已打款'};
const badge=status=>`<span class="status-pill ${escape(status)}">${statusLabels[status]||'待审核'}</span>`;
const root=document.querySelector('#app');
const state={config:null,view:location.pathname.startsWith('/admin')?'admin':'guest',step:1,guestAuthenticated:false,submissionKey:crypto.randomUUID(),draftStatus:{phase:'loading',message:'',lastSaved:''},applicant:{name:'',mobile:'',organization:'',contactPerson:''},inviteCode:'',payment:{method:'bank',accountName:'',accountNumber:'',bankName:'',bankBranch:''},expenses:[],supportingFiles:[],note:'',consent:false,errors:{},busy:false,success:null,lookup:{mobile:'',result:null,error:'',busy:false},admin:{authenticated:false,loading:false,items:[],showTrash:false,trashCount:0,filter:'all',query:'',error:'',selected:null,password:'',reviewStatus:'pending',reviewNote:''}};
let toastTimer;
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='toast',4500)}
async function api(url,options={}){const headers={...options.headers};if(options.body&&typeof options.body==='string')headers['Content-Type']='application/json';const response=await fetch(url,{credentials:'same-origin',...options,headers});const type=response.headers.get('content-type')||'';const result=type.includes('json')?await response.json():await response.text();if(!response.ok){const e=new Error(result.message||result.error||'请求失败，请稍后再试');e.status=response.status;e.code=result.error;throw e}return result}
const json=(method,value)=>({method,body:JSON.stringify(value)});
function header(){return `<header class="shell-header"><div class="header-inner"><a href="/" class="brand" aria-label="零一万物 · 嘉宾服务首页"><img class="brand-logo" src="/assets/logo-green.png" width="558" height="205" alt="零一万物 01.AI"/><span class="brand-divider"></span><span class="conference-name">2026 西南生态大会<small>01.AI Eco Summit（2026 · Neijiang）</small></span></a><nav class="header-nav" aria-label="主要导航"><button class="nav-link ${state.view==='guest'?'active':''}" data-action="guest">${icon('receipt')}报销申请</button><button class="nav-link ${state.view==='lookup'?'active':''}" data-action="lookup">${icon('search')}进度查询</button><span class="nav-divider"></span><a class="nav-link admin-nav ${state.view==='admin'?'active':''}" href="/admin">${icon('grid')}工作台</a></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="footer-brand"><img src="/assets/logo-green.png" width="558" height="205" alt="零一万物 01.AI"/><span>© ${new Date().getFullYear()} 零一万物<span class="footer-dot">·</span>西南生态大会</span></div><span class="footer-note">${icon('shield')}您的资料仅用于本次会议报销</span></footer>`}
function steps(){return `<div class="steps" aria-label="申请进度">${['基本信息','费用与票据','确认提交'].map((s,i)=>`${i?'<div class="step-line"></div>':''}<div class="step ${state.step===i+1?'active':state.step>i+1?'complete':''}" ${state.step===i+1?'aria-current="step"':''}><span class="step-circle">${state.step>i+1?icon('check'):String(i+1).padStart(2,'0')}</span>${s}</div>`).join('')}</div>`}
function field(label,name,value,{placeholder='',required=false,optional=false,type='text',full=false,hint='',autocomplete='',inputmode='',maxlength=120}={}){const err=state.errors[name];return `<div class="field ${full?'full':''} ${err?'invalid':''}"><label for="${name}">${label}${required?'<span class="required">*</span>':''}${optional?'<span class="optional">选填</span>':''}</label><input id="${name}" name="${name}" type="${type}" value="${escape(value)}" placeholder="${placeholder}" ${autocomplete?`autocomplete="${autocomplete}"`:''} maxlength="${maxlength}" ${inputmode?`inputmode="${inputmode}"`:""} ${required?'aria-required="true"':''} ${err?`aria-invalid="true" aria-describedby="error-${name}"`:''}/>${err?`<p class="field-error" id="error-${name}">${escape(err)}</p>`:hint?`<p class="field-hint">${hint}</p>`:''}</div>`}
function side(){return `<aside class="side-stack"><div class="guide-card"><div class="eyebrow">CONNECTED BY AI</div><h2>赴一场 AI 之约，<br>余下交给我们。</h2><p>感谢您奔赴甜城内江。<br>愿每一段旅程，都有妥帖的回应。</p><div class="guide-signature"><span class="guide-line"></span><span>零一万物 · 嘉宾服务</span></div></div><div class="side-card"><h2 class="side-heading">${icon('receipt')}提交前，准备这些</h2><ol class="checklist"><li><span class="list-number">01</span><div><strong>报销票据</strong>住宿发票、铁路电子客票、航空电子客票行程单等有效票据，以财务要求为准。</div></li><li><span class="list-number">02</span><div><strong>对应行程材料</strong>打车行程单等可作为补充附件；航空电子客票行程单请上传到机票费用中。</div></li><li><span class="list-number">03</span><div><strong>核对识别信息</strong>请核对金额、发票号码与抬头；自动识别结果仅供填写参考。</div></li></ol><div class="mini-divider"></div><div class="side-footer">请准备本人银行卡或支付宝账号。<br>收款资料仅用于本次大会报销汇款。</div></div><div class="help-card">${icon('help')}<div><strong>填写遇到问题？</strong><p>请联系您的大会对接人协助处理</p></div></div></aside>`}

function paymentForm(){
 const p=state.payment,bank=p.method==='bank';
 return `<div class="form-separator"></div><div class="section-heading payment-heading"><h3 class="section-title">${icon('wallet')}收款信息</h3><span class="optional">供大会审核后汇款</span></div><p class="section-caption">请选择一种收款方式，填写与账户实名认证一致的姓名。</p><div class="payment-methods" role="radiogroup" aria-label="收款方式">${[['bank','银行卡','银行转账'],['alipay','支付宝','手机号或邮箱账号']].map(([value,label,hint])=>`<label class="payment-method ${p.method===value?'selected':''}"><input type="radio" name="payment-method" value="${value}" ${p.method===value?'checked':''}/><span><strong>${label}</strong><small>${hint}</small></span>${icon('check')}</label>`).join('')}</div><div class="form-grid payment-fields">${field(bank?'开户姓名':'支付宝实名姓名','payment-accountName',p.accountName,{placeholder:'请填写收款账户的真实姓名',required:true,maxlength:40,autocomplete:'off'})}${bank?field('开户银行','payment-bankName',p.bankName,{placeholder:'例如：中国工商银行',required:true,maxlength:100,autocomplete:'off'}):''}${field(bank?'银行卡号':'支付宝账号','payment-accountNumber',p.accountNumber,{placeholder:bank?'请填写本人银行卡号':'请填写支付宝绑定手机号或邮箱',required:true,full:!bank,maxlength:bank?35:254,autocomplete:'off',inputmode:bank?'numeric':'email'})}${bank?field('开户支行','payment-bankBranch',p.bankBranch,{placeholder:'例如：内江分行某某支行',optional:true,maxlength:120,autocomplete:'off'}):''}</div><div class="notice payment-notice">${icon('lock')}<div>请仔细核对收款人和账号，避免影响到账。只有获授权的工作人员可以查看和导出完整收款信息。</div></div>`;
}
function paymentDetails(p){
 if(!p?.method)return '<div class="notice">这份历史申请尚未收集收款信息，请联系嘉宾补充。</div>';
 const bank=p.method==='bank';
 const rows=[['收款方式',bank?'银行卡转账':'支付宝'],['收款人姓名',p.accountName],[bank?'银行卡号':'支付宝账号',p.accountNumber],...(bank?[['开户银行',p.bankName],['开户支行',p.bankBranch||'未填写']]:[])];
 return `<div class="review-grid payment-review-grid">${rows.map(([label,value])=>`<div class="review-item ${label==='银行卡号'||label==='支付宝账号'?'account-number-item':''}"><label>${label}</label><span>${escape(value)}</span></div>`).join('')}</div>`;
}
function validatePayment(){
 const p=state.payment;
 p.accountName=p.accountName.trim();p.accountNumber=p.method==='bank'?p.accountNumber.replace(/\s/g,''):p.accountNumber.trim();p.bankName=p.bankName.trim();p.bankBranch=p.bankBranch.trim();
 if(!p.accountName)state.errors['payment-accountName']='请填写收款账户的实名姓名';
 if(p.method==='bank'){
  if(!/^\d{12,25}$/.test(p.accountNumber))state.errors['payment-accountNumber']='请填写 12–25 位数字银行卡号';
  if(!p.bankName)state.errors['payment-bankName']='请填写开户银行';
 }else if(p.method==='alipay'){
  const phone=/^(?:\+?86)?1[3-9][0-9]{9}$/.test(p.accountNumber);const email=/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$/.test(p.accountNumber);const local=p.accountNumber.split('@')[0];if(!phone&&!(email&&!local.startsWith('.')&&!local.endsWith('.')&&!local.includes('..')))state.errors['payment-accountNumber']='请填写支付宝绑定的手机号或邮箱';
 }else state.errors['payment-accountNumber']='请选择收款方式';
 return !Object.keys(state.errors).some(k=>k.startsWith('payment-'));
}

function basicStep(){return `<div class="card-body"><div class="section-heading"><h2 class="section-title">${icon('user')}先认识一下您</h2><span class="section-count">STEP 01 / 03</span></div><div class="form-grid">${field('嘉宾姓名','name',state.applicant.name,{placeholder:'请填写真实姓名',required:true,autocomplete:'name',maxlength:40})}${field('联系手机','mobile',state.applicant.mobile,{placeholder:'用于材料核实与进度查询',required:true,type:'tel',autocomplete:'tel',maxlength:20})}${field('所在单位','organization',state.applicant.organization,{placeholder:'请填写单位或机构名称',required:true,autocomplete:'organization'})}${field('大会对接人','contactPerson',state.applicant.contactPerson,{placeholder:'方便工作人员联系核实',optional:true,maxlength:40})}</div><div class="form-separator"></div>${state.guestAuthenticated?`<div class="notice invite-verified">${icon('check')}<div>嘉宾邀请码已验证，可继续填写。</div></div>`:`<div class="field invite-field ${state.errors.inviteCode?'invalid':''}"><label for="inviteCode">嘉宾邀请码<span class="required">*</span></label><div class="input-with-icon">${icon('lock')}<input id="inviteCode" name="inviteCode" type="password" value="${escape(state.inviteCode)}" placeholder="请输入对接人提供的邀请码" maxlength="100" autocomplete="off" aria-required="true"/></div>${state.errors.inviteCode?`<p class="field-error">${escape(state.errors.inviteCode)}</p>`:'<p class="field-hint">本服务面向受邀 VIP 嘉宾，邀请码由大会对接人提供。</p>'}</div>`}${paymentForm()}<div class="notice" style="margin-top:26px">${icon('shield')}<div><strong>资料仅用于本次会议报销</strong><br>请核对姓名、联系方式和收款信息，便于工作人员审核与汇款。</div></div></div>`}
function categoryOptions(current){return `<option value="" ${!current?'selected':''}>请选择费用类型</option>`+(state.config?.categories||[{id:'rail',label:'高铁 / 火车'},{id:'flight',label:'机票'},{id:'taxi',label:'打车'},{id:'hotel',label:'住宿'},{id:'other',label:'其他'}]).map(c=>`<option value="${escape(c.id)}" ${current===c.id?'selected':''}>${escape(c.label)}</option>`).join('')}
function ticketUploadHint(category){return category==='flight'?'<p class="ticket-upload-hint">机票请上传电子发票（航空运输电子客票行程单），报销金额按票面合计核对。</p>':category==='rail'?'<p class="ticket-upload-hint">火车、高铁请上传电子发票（铁路电子客票），报销金额按票价核对。</p>':''}
function applyOcrCategory(e){if(!e.category&&['rail','flight'].includes(e.ocr?.suggestedCategory))e.category=e.ocr.suggestedCategory}
function categoryLabel(id){return state.config?.categories?.find(c=>c.id===id)?.label||id||'其他'}
function expenseField(e,i,label,key,{type='text',required=false,full=false,placeholder=''}={}){
 const id=`expense-${i}-${key}`;
 const recognized=e.ocr?.fields?.[key];
 const auto=recognized!==''&&recognized!=null&&String(recognized)===String(e[key]);
 return `<div class="field ${full?'full':''} ${state.errors[id]?'invalid':''}"><label for="${id}">${label}${required?'<span class="required">*</span>':''}${auto?'<span class="auto-tag">已识别</span>':''}</label><input id="${id}" data-expense="${e.uid}" data-key="${key}" type="${type}" value="${escape(e[key])}" placeholder="${placeholder}" ${e.recognizing||e.removing||e.uploading?'disabled':''} ${type==='number'?'min="0" max="100000" step="0.01" inputmode="decimal"':''} ${type==='text'?'maxlength="160"':''} ${required?'aria-required="true"':''}/>${state.errors[id]?`<p class="field-error">${escape(state.errors[id])}</p>`:''}</div>`}
function fileTop(file,{remove=true,support=false}={}){return `<div class="expense-top"><div class="file-info"><span class="file-badge ${file.mime==='application/pdf'?'pdf':''}">${icon('file')}</span><div style="min-width:0"><div class="file-title" title="${escape(file.name)}">${escape(file.name)}</div><div class="file-meta">${byteSize(file.size)}${support?' · 补充附件':''}</div></div></div><div class="button-group">${file.fileId?`<a class="preview-link" href="/api/files/${encodeURIComponent(file.fileId)}" target="_blank" rel="noopener">查看${icon('external')}</a>`:''}${remove?`<button class="icon-button" type="button" data-action="remove-file" data-id="${escape(file.uid)}" data-support="${support}" aria-label="移除 ${escape(file.name)}" ${file.removing?'disabled':''}>${icon('close')}</button>`:''}</div></div>`}

function blankExpense(){return {uid:crypto.randomUUID(),name:'',size:0,mime:'',fileId:'',uploading:false,paymentProofs:[],category:'',amount:'',invoiceNumber:'',date:'',buyerName:'',buyerTaxId:'',sellerName:'',sellerTaxId:'',netAmount:'',taxAmount:'',note:''}}
function expenseCard(e,i){
 const count=Object.values(e.ocr?.fields||{}).filter(v=>v!==''&&v!=null).length,warnings=e.ocr?.warnings||[];
 const heading=`<div class="expense-entry-heading"><div class="expense-entry-title"><span class="expense-index">${String(i+1).padStart(2,'0')}</span><div><h3>第 ${i+1} 笔费用</h3><p>每笔分别填写用途与票据</p></div></div><button class="text-button remove-expense" type="button" data-action="remove-expense" data-id="${e.uid}" ${e.uploading||e.recognizing||e.removing?'disabled':''}>${icon('close')}删除本笔</button></div><div class="expense-entry-purpose"><div class="form-grid"><div class="field ${state.errors[`expense-${i}-category`]?'invalid':''}"><label for="category-${i}">费用类型<span class="required">*</span></label><select id="category-${i}" data-expense="${e.uid}" data-key="category" ${e.recognizing||e.uploading||e.removing?'disabled':''}>${categoryOptions(e.category)}</select>${state.errors[`expense-${i}-category`]?`<p class="field-error">${escape(state.errors[`expense-${i}-category`])}</p>`:''}</div>${expenseField(e,i,'费用用途说明','note',{placeholder:'例如：11月参会住宿 / 返程机票'})}</div></div>`;
 let body='';
 if(e.removing)body='<div class="uploading"><span class="spinner"></span>正在移除票据…</div>';
 else if(e.uploading)body=`<div class="uploading"><span class="spinner"></span>正在上传并识别 ${escape(e.name)}…</div>`;
 else if(!e.fileId)body=`<div class="expense-upload">${uploadZone(false,e.uid)}${ticketUploadHint(e.category)}${state.errors[`expense-${i}-file`]?`<p class="field-error">${escape(state.errors[`expense-${i}-file`])}</p>`:''}</div>`;
 else body=`${fileTop(e)}<div class="ocr-result ${count?'has-fields':''}" aria-live="polite">${e.ocr?.documentLabel?`<div class="ticket-type">${icon('receipt')}${escape(e.ocr.documentLabel)}</div>`:''}<div class="ocr-result-top"><span class="ocr-result-title">${e.recognizing?'<span class="spinner"></span>':icon(count?'spark':'edit')}${e.recognizing?'正在重新识别…':count?`识别到 ${count} 项票据信息`:'请补充票据信息'}</span><button class="text-button" type="button" data-action="recognize" data-id="${e.uid}" ${e.recognizing||e.removing||e.uploading?'disabled':''}>${icon('refresh')}重新识别</button></div><p>${count?'请对照原票核对以下信息，识别结果可直接修改。':escape(e.ocr?.message||'未提取到发票字段，请手动填写或上传清晰原件。')}</p>${warnings.length?`<ul class="ocr-warnings">${warnings.map(w=>`<li>${escape(w)}</li>`).join('')}</ul>`:''}</div><div class="expense-fields"><div class="form-grid">${expenseField(e,i,'报销金额（元）','amount',{type:'number',required:true,placeholder:'默认填入票面总金额，请核对'})}${expenseField(e,i,'开票日期','date',{type:'date'})}${expenseField(e,i,'发票号码','invoiceNumber',{full:true,placeholder:'按票面填写，无此项可留空'})}</div><div class="invoice-party-heading"><span>抬头与税号</span><small>按票面区分购买方与销售方</small></div><div class="form-grid">${expenseField(e,i,'购买方名称','buyerName',{placeholder:'票面上的购买方名称'})}${expenseField(e,i,'购买方税号','buyerTaxId',{placeholder:'无此项可留空'})}${expenseField(e,i,'销售方名称','sellerName',{placeholder:'开具发票的单位名称'})}${expenseField(e,i,'销售方税号','sellerTaxId',{placeholder:'无此项可留空'})}${expenseField(e,i,'不含税金额（元）','netAmount',{type:'number',placeholder:'票面金额，不额外计入报销'})}${expenseField(e,i,'税额（元）','taxAmount',{type:'number',placeholder:'票面税额，无此项可留空'})}</div></div><div class="ocr-note">${icon('info')}<span>文字识别用于辅助录入，不代表发票验真或审核通过。</span></div>`;
 return `<article class="expense-card expense-entry" id="entry-${e.uid}">${heading}${body}${paymentProofSection(e)}</article>`;
}
function total(){return state.expenses.filter(e=>e.fileId).reduce((sum,e)=>sum+Math.round(Number(e.amount||0)*100),0)/100}
function categoryTotals(){
 const groups=new Map();for(const e of state.expenses.filter(e=>e.fileId)){const g=groups.get(e.category)||{count:0,cents:0};g.count++;g.cents+=Math.round(Number(e.amount||0)*100);groups.set(e.category,g)}
 return [...groups].map(([key,g])=>`<div><span>${escape(key?categoryLabel(key):'待选类型')}<small>${g.count} 笔</small></span><strong>¥ ${money(g.cents/100)}</strong></div>`).join('');
}
function refreshExpenseTotals(){const t=document.querySelector('#live-total');if(t)t.innerHTML=`<small>¥</small>${money(total())}`;const g=document.querySelector('#category-totals');if(g)g.innerHTML=categoryTotals()}
function uploadZone(support=false,uid=''){
 const id=support?'support-input':`file-input-${uid}`;
 return `<label class="upload-zone" data-dropzone="${support?'support':'expense'}" data-target="${uid}" tabindex="0" role="button" for="${id}"><span class="upload-symbol">${icon(support?'file':'upload')}</span><h3>${support?'添加行程单或其他补充材料':'上传本笔费用的票据'}</h3><p>${support?'补充附件不单独计入报销金额':'一张票据对应一笔费用；上传后自动识别'}</p><div class="file-types"><span>PDF</span><span>JPG</span><span>PNG</span><span>每份 ≤ ${Math.round((state.config?.maxFileSize||15728640)/1024/1024)} MB</span></div><input class="visually-hidden" type="file" id="${id}" accept="image/jpeg,image/png,application/pdf" ${support?'multiple':''} data-upload="${support?'support':'expense'}" data-target="${uid}"/></label>`;
}
function expenseStep(){return `<div class="card-body"><div class="section-heading"><h2 class="section-title">${icon('receipt')}整理您的费用与票据</h2><span class="section-count">STEP 02 / 03</span></div><p class="section-caption">住宿、机票、高铁等请分别新增一笔费用，选择用途并上传对应票据。</p>${state.errors.expenses?`<div class="error-banner">${escape(state.errors.expenses)}</div>`:''}<div class="expense-list">${state.expenses.map(expenseCard).join('')}</div><button class="add-expense-button" type="button" data-action="add-expense" ${state.expenses.length>=(state.config?.maxFiles||12)||fileCount()>=(state.config?.maxFiles||12)?'disabled':''}><span>＋</span><strong>新增一笔费用</strong><small>住宿 / 机票 / 高铁 / 打车 / 其他</small></button><div class="expense-summary"><div class="total-bar"><span>已上传 <b id="expense-count">${state.expenses.filter(e=>e.fileId).length}</b> 笔费用 · 申请金额合计</span><strong class="money" id="live-total"><small>¥</small>${money(total())}</strong></div><div class="category-totals" id="category-totals">${categoryTotals()}</div></div><div class="form-separator"></div><div class="section-heading" style="margin-bottom:16px"><h3 class="section-title" style="font-size:14px">补充附件<span class="optional">选填</span></h3></div><p class="section-caption" style="margin-top:-7px">打车行程单等证明可在此补充。铁路电子客票、航空电子客票行程单请作为对应费用的票据上传。</p>${uploadZone(true)}<div class="expense-list">${state.supportingFiles.map(f=>f.uploading?`<div class="expense-card"><div class="uploading"><span class="spinner"></span>正在上传 ${escape(f.name)}…</div></div>`:`<div class="expense-card">${fileTop(f,{support:true})}</div>`).join('')}</div><div class="field"><label for="note">给工作人员的留言<span class="optional">选填</span></label><textarea id="note" name="note" maxlength="2000" placeholder="如有特殊情况，欢迎在这里补充说明">${escape(state.note)}</textarea></div></div>`}
function reviewStep(){return `<div class="card-body"><div class="section-heading"><h2 class="section-title">${icon('check')}最后，再核对一下</h2><span class="section-count">STEP 03 / 03</span></div><p class="section-caption">确认无误后提交，工作人员会审核您提供的材料。</p><div class="review-block"><div class="review-heading">嘉宾信息<button class="text-button" data-action="step" data-step="1" type="button">修改</button></div><div class="review-grid">${[['嘉宾姓名',state.applicant.name],['联系手机',state.applicant.mobile],['所在单位',state.applicant.organization||'未填写'],['大会对接人',state.applicant.contactPerson||'未填写']].map(([k,v])=>`<div class="review-item"><label>${k}</label><span>${escape(v)}</span></div>`).join('')}</div></div><div class="review-block"><div class="review-heading">收款信息<button class="text-button" data-action="step" data-step="1" type="button">修改</button></div>${paymentDetails(state.payment)}<p class="field-hint">请再次核对收款人和账号，财务会按此信息安排汇款。</p></div><div class="review-block"><div class="review-heading">费用与材料<button class="text-button" data-action="step" data-step="2" type="button">修改</button></div>${state.expenses.map(e=>`<div class="review-expense"><div><strong>${escape(categoryLabel(e.category))}</strong><small>${escape(e.name)}${e.note?` · ${escape(e.note)}`:''}${e.paymentProofs?.length?` · 支付截图 ${e.paymentProofs.length} 张`:''}</small></div><span class="amount">¥ ${money(e.amount)}</span></div>`).join('')}${state.supportingFiles.length?`<p class="sub-text" style="margin-top:16px">另有 ${state.supportingFiles.length} 份补充附件</p>`:''}${state.note?`<p class="sub-text" style="margin-top:15px;white-space:pre-wrap">留言：${escape(state.note)}</p>`:''}</div><div class="total-bar"><span>共 ${state.expenses.length} 笔费用 · 申请金额合计</span><strong class="money"><small>¥</small>${money(total())}</strong></div><label class="consent"><input type="checkbox" name="consent" ${state.consent?'checked':''}/><span>我已核对上述资料，同意大会工作人员为本次报销审核、联系、汇款和归档使用所提交的信息。</span></label>${state.errors.consent?`<p class="field-error" style="margin-left:25px">${escape(state.errors.consent)}</p>`:''}<details class="privacy-details"><summary>了解资料使用方式</summary><p>本页面收集您的姓名、联系方式、费用、票据附件和所选方式的收款信息，用于本次大会报销审核与汇款。票据会在本服务所在的设备或服务器上处理，只有获授权的工作人员可以查看与导出。工作人员将按您填写的账号安排汇款，普通进度查询只显示脱敏账号；如需更正或申请删除资料，请联系大会对接人。提交不代表审核通过，保存期限以大会财务归档要求为准。</p></details>${state.errors.submit?`<div class="error-banner">${escape(state.errors.submit)}</div>`:''}</div>`}
function guest(){return `<main class="page guest-page"><figure class="event-hero ${state.step>1||state.success?'event-hero-hidden':''}"><img class="event-kv" src="/assets/event-kv.webp" width="1267" height="632" alt="甜城 AI 链 · 零一万物2026西南生态大会 · 01.AI Eco Summit（2026 · Neijiang）" fetchpriority="high"/><figcaption class="hero-caption"><span>01.AI Eco Summit（2026 · Neijiang）</span><span>${icon('shield')}VIP 嘉宾服务</span></figcaption></figure><div class="intro-row" id="reimbursement"><div><div class="eyebrow">GUEST REIMBURSEMENT</div><h1 class="page-title">参会报销，轻松提交。</h1><p class="page-subtitle">把票据交给我们，把时间留给相聚。</p></div><div class="intro-tag">${icon('lock')}专属嘉宾通道</div></div><div class="guest-layout"><section class="main-card" aria-label="报销申请">${state.success?success():`${steps()}${draftStatusHtml()}<form id="guest-form" novalidate>${state.step===1?basicStep():state.step===2?expenseStep():reviewStep()}<div class="card-actions">${state.step>1?`<button type="button" class="btn btn-ghost" data-action="previous">${icon('back')}上一步</button>`:`<span class="action-note">${icon('lock')}资料仅限授权工作人员查看</span>`}<button class="btn btn-primary" type="submit" ${state.busy||hasPendingFiles()?'disabled':''}>${state.busy?'<span class="spinner"></span>':state.step===3?icon('check'):''}${state.busy?'正在处理…':state.step===3?'确认提交':'下一步'}${state.step<3&&!state.busy?icon('arrow'):''}</button></div></form>`}</section>${side()}</div>${footer()}</main>`}
function success(){const s=state.success;return `<div class="success-body"><div class="success-mark">${icon('check')}</div><div class="eyebrow" style="justify-content:center">ALL SET, THANK YOU</div><h2 style="margin-top:12px">材料已收到，感谢您的配合。</h2><p>工作人员会尽快核对，如需补充将通过您预留的手机联系。</p><div class="reference-box"><small>您的预留手机号</small><div class="reference-code">${escape(state.applicant.mobile)}</div><p class="field-hint">以后使用此手机号即可查询报销进度</p></div><div class="success-detail">共 ${s.expenseCount} 笔费用 · 合计 ¥ ${money(s.totalAmount)}</div><div class="button-group" style="justify-content:center"><button class="btn btn-secondary" data-action="lookup-success">查询处理进度${icon('arrow')}</button></div><p class="side-footer" style="margin:22px 0 0">${s.submittedAt?'提交时间：'+date(s.submittedAt)+'<br>':''}请保留票据原件，是否寄送以财务要求为准。</p></div>`}
function lookupResult(r,index){return `<div class="lookup-result"><div class="review-heading">${r.createdAt?date(r.createdAt)+' 提交的申请':`申请 ${index+1}`}${badge(r.status)}</div><div class="lookup-timeline">费用合计：¥ ${money(r.totalAmount)}${r.expenseCount?` · ${r.expenseCount} 笔费用`:''}${r.updatedAt?`<br>最后更新：${date(r.updatedAt)}`:''}</div><div class="notice">${icon('info')}<div>${escape(r.reviewNote||(r.status==='pending'?'您的材料已收到，正在等待工作人员审核。':r.status==='needs_info'?'请联系大会对接人确认需要补充的材料。':r.status==='paid'?'工作人员已标记为已打款，到账情况以您的收款账户为准。':'材料已审核通过，付款进度请咨询大会对接人。'))}</div></div></div>`}
function lookup(){const l=state.lookup;return `<main class="page lookup-page"><div class="intro-row"><div><div class="eyebrow">APPLICATION STATUS</div><h1 class="page-title">每一份提交，都有回应。</h1><p class="page-subtitle">填写提交时预留的手机号，查看材料处理进度。</p></div></div><section class="main-card lookup-card"><div class="card-body"><div class="section-heading"><h2 class="section-title">${icon('search')}查询报销进度</h2></div><form id="lookup-form"><div class="form-grid">${field('预留手机号','lookup-mobile',l.mobile,{placeholder:'提交申请时填写的手机',required:true,type:'tel',maxlength:20,full:true,autocomplete:'tel'})}</div>${l.error?`<div class="error-banner">${escape(l.error)}</div>`:''}<button class="btn btn-primary" style="margin-top:24px" ${l.busy?'disabled':''}>${l.busy?'<span class="spinner"></span>':icon('search')}${l.busy?'正在查询…':'查询进度'}</button></form>${l.result?(l.result.items?.length?`<p class="field-hint" style="margin-top:25px">查询到 ${l.result.items.length} 份申请，按提交时间排列。</p>${l.result.items.map(lookupResult).join('')}`:'<div class="notice" style="margin-top:25px">'+icon('info')+'<div>暂无该手机号的申请，请核对提交时预留的号码。</div></div>'):''}</div></section>${footer()}</main>`}

function login(){return `<main class="page login-page"><div class="login-layout"><div class="login-visual"><img class="login-logo" src="/assets/logo-white.png" width="558" height="205" alt="零一万物 01.AI"/><div class="login-brand-copy"><div class="eyebrow">ORGANIZER WORKSPACE</div><h2>相聚甜城，<br>每一份奔赴都有回应。</h2><p>零一万物2026西南生态大会<br>嘉宾报销材料管理</p></div><span class="login-location">01.AI Eco Summit（2026 · Neijiang）</span></div><form class="login-form" id="login-form"><div class="eyebrow">WELCOME BACK</div><h2>工作人员登录</h2><p>仅限获得授权的大会工作人员使用</p>${field('管理密码','admin-password',state.admin.password,{placeholder:'请输入管理密码',required:true,type:'password',autocomplete:'current-password',maxlength:200})}${state.admin.error?`<div class="error-banner">${escape(state.admin.error)}</div>`:''}<button class="btn btn-primary" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':icon('lock')}${state.busy?'正在登录…':'进入工作台'}</button><p class="field-hint" style="margin-top:19px">管理密码由服务管理员配置，请勿向嘉宾分享。</p></form></div>${footer()}</main>`}
function filteredItems(){const a=state.admin,q=a.query.trim().toLowerCase();return a.items.filter(i=>(a.filter==='all'||i.status===a.filter)&&(!q||[i.reference,i.applicant?.name,i.applicant?.mobile,i.applicant?.organization].some(v=>String(v||'').toLowerCase().includes(q))))}
function adminTable(){
 const a=state.admin,items=filteredItems(),disabled=state.busy||a.loading;
 return `${items.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>嘉宾 / 单位</th><th>申请编号</th><th>费用金额</th><th>票据</th><th>${a.showTrash?'删除时间':'提交时间'}</th><th>处理状态</th><th>操作</th></tr></thead><tbody>${items.map(i=>`<tr><td><div class="person-cell"><span class="avatar">${escape((i.applicant?.name||'?').slice(-1))}</span><div><strong>${escape(i.applicant?.name)}</strong><div class="sub-text">${escape(i.applicant?.organization||'未填写单位')}</div></div></div></td><td><span class="application-ref">${escape(i.reference)}</span></td><td class="table-amount">¥ ${money(i.totalAmount)}</td><td class="table-file-count">${i.expenseCount||i.expenses?.length||0} 笔${i.supportingFiles?.length?` + ${i.supportingFiles.length} 附件`:''}</td><td class="table-date">${date(a.showTrash?i.deletedAt:i.createdAt)}</td><td>${badge(i.status)}</td><td><div class="record-actions"><button class="text-button" data-action="review" data-id="${escape(i.id)}" ${disabled?'disabled':''}>${a.showTrash?'查看详情':'查看审核'}</button><button class="text-button ${a.showTrash?'':'danger-text'}" data-action="${a.showTrash?'restore-submission':'delete-submission'}" data-id="${escape(i.id)}" ${disabled?'disabled':''}>${a.showTrash?'恢复':'删除'}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">${icon('receipt')}</div><h3>${a.items.length?'没有找到匹配的申请':a.showTrash?'回收站为空':'还没有收到申请'}</h3><p>${a.items.length?'试试其他姓名、编号或处理状态。':a.showTrash?'删除的申请会保留在这里，可以恢复。':'将嘉宾提交地址与邀请码分享给受邀嘉宾，申请会显示在这里。'}</p></div>`}<div class="table-bottom"><span>共 ${items.length} 条${a.showTrash?'已删除记录':a.filter!=='all'||a.query?'匹配记录':'申请记录'}</span><span>${a.showTrash?'回收站记录不计入报销汇总':'数据仅限大会报销使用'}</span></div>`;
}
function dashboard(){
 const a=state.admin,allTotal=a.items.reduce((sum,i)=>sum+Number(i.totalAmount||0),0);
 return `<main class="page admin-page"><div class="intro-row"><div><div class="eyebrow">ORGANIZER WORKSPACE</div><h1 class="page-title">${a.showTrash?'申请回收站':'嘉宾报销工作台'}</h1><p class="page-subtitle">${a.showTrash?'已删除的申请保留在这里，可核对后恢复。':'从材料到归档，每一笔都清晰。'}</p></div><div class="button-group"><button class="btn btn-secondary" data-action="toggle-trash" ${state.busy||a.loading?'disabled':''}>${icon(a.showTrash?'back':'receipt')}${a.showTrash?'返回申请':`回收站${a.trashCount?' · '+a.trashCount:''}`}</button><button class="btn btn-secondary" data-action="refresh" ${state.busy?'disabled':''}>${icon('refresh',a.loading?'refreshing':'')}刷新</button>${!a.showTrash?`<a class="btn btn-primary" href="${exportUrl('xlsx')}">${icon('download')}导出报销表</a>`:''}</div></div>${!a.showTrash?`<div class="admin-summary"><div class="stat-card"><div><div class="stat-label">收到申请</div><div class="stat-value">${a.items.length}<small>份</small></div></div><span class="stat-icon">${icon('user')}</span></div><div class="stat-card"><div><div class="stat-label">待审核 / 待补充</div><div class="stat-value">${a.items.filter(i=>i.status==='pending'||i.status==='needs_info').length}<small>份</small></div></div><span class="stat-icon">${icon('clock')}</span></div><div class="stat-card"><div><div class="stat-label">已审核通过</div><div class="stat-value">${a.items.filter(i=>i.status==='approved'||i.status==='paid').length}<small>份</small></div></div><span class="stat-icon">${icon('check')}</span></div><div class="stat-card featured"><div><div class="stat-label">申请金额合计（元）</div><div class="stat-value" style="font-size:${allTotal>999999?22:27}px">${money(allTotal)}</div></div><span class="stat-icon">${icon('wallet')}</span></div></div><div class="admin-banner"><div><strong>收集资料，从一个链接开始</strong><span>嘉宾一次提交费用、票据与收款信息；工作人员核对后安排汇款。</span></div><div class="button-group"><button class="btn btn-ghost" data-action="copy-link">${icon('copy')}复制提交地址</button><a class="btn btn-ghost" href="${exportUrl('zip')}">${icon('download')}下载票据归档</a></div></div>`:`<div class="notice trash-notice">${icon('info')}<div>回收站中的申请不会出现在嘉宾查询、报销统计和导出文件中。原票据与收款资料保留，恢复后可继续审核。</div></div>`}${a.error?`<div class="error-banner">${escape(a.error)}</div>`:''}<section class="main-card"><div class="toolbar"><div class="tabs" aria-label="按处理状态筛选">${[['all',a.showTrash?'全部已删除':'全部申请'],...Object.entries(statusLabels)].map(([k,v])=>`<button class="filter-tab ${a.filter===k?'active':''}" data-action="filter" data-filter="${k}">${v}${k==='pending'?` <span class="tab-count">${a.items.filter(i=>i.status==='pending').length}</span>`:''}</button>`).join('')}</div><div class="search-box">${icon('search')}<input class="filter-input" type="search" id="admin-search" placeholder="搜索嘉宾、手机或申请编号" value="${escape(a.query)}" aria-label="搜索申请"/></div></div><div id="admin-table">${adminTable()}</div></section><div class="admin-bottom-note"><span class="field-hint">${a.showTrash?'如相同票据已用于另一份有效申请，请先核对重复记录再恢复。':'提示：OCR 结果仅供参考，请结合票据原件核对后再审核。'}</span><button class="text-button" data-action="logout">退出登录</button></div>${footer()}</main>${a.selected?drawer():''}`;
}

function exportUrl(ext){const params=new URLSearchParams();if(state.admin.filter!=='all')params.set('status',state.admin.filter);if(state.admin.query)params.set('q',state.admin.query);return `/api/admin/export.${ext}${params.size?'?'+params.toString():''}`}
function drawer(){const i=state.admin.items.find(i=>String(i.id)===String(state.admin.selected));if(!i)return '';return `<div class="modal-overlay" data-action="close-drawer" id="review-overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-header"><div><h2 id="drawer-title">申请详情</h2><small>${escape(i.reference)}</small></div><button class="icon-button" data-action="close-drawer" aria-label="关闭详情">${icon('close')}</button></div><form id="review-form"><div class="drawer-body"><div class="review-heading">${escape(i.applicant?.name)}的申请${badge(i.status)}</div><div class="review-grid" style="margin:21px 0 28px">${[['联系手机',i.applicant?.mobile],['所在单位',i.applicant?.organization||'未填写'],['大会对接人',i.applicant?.contactPerson||'未填写'],['提交时间',date(i.createdAt)]].map(([k,v])=>`<div class="review-item"><label>${k}</label><span>${escape(v)}</span></div>`).join('')}</div><h3 class="drawer-section-title">收款信息 · 仅授权工作人员可见</h3><div class="review-block">${paymentDetails(i.payment)}</div><h3 class="drawer-section-title">费用与票据 · ${i.expenses?.length||0} 笔</h3>${(i.expenses||[]).map(e=>`<div class="review-block"><div class="review-heading">${escape(categoryLabel(e.category))}<span>¥ ${money(e.amount)}</span></div><div class="file-info" style="justify-content:space-between"><div class="file-title" style="font-size:11px;color:#94a185">${escape(e.file?.name||e.fileName||'票据文件')}</div><a class="preview-link" href="/api/files/${encodeURIComponent(e.file?.id||e.fileId)}" target="_blank" rel="noopener">查看原件${icon('external')}</a></div><div class="review-grid" style="margin-top:14px">${[['发票号码',e.invoiceNumber||'未填写'],['开票日期',e.date||'未填写'],['购买方名称',e.buyerName||'未填写'],['购买方税号',e.buyerTaxId||'未填写'],['销售方名称',e.sellerName||'未填写'],['销售方税号',e.sellerTaxId||'未填写'],['不含税金额',e.netAmount!==''&&e.netAmount!=null?'¥ '+money(e.netAmount):'未填写'],['税额',e.taxAmount!==''&&e.taxAmount!=null?'¥ '+money(e.taxAmount):'未填写'],['费用说明',e.note||'无']].map(([k,v])=>`<div class="review-item"><label>${k}</label><span style="font-size:11px">${escape(v)}</span></div>`).join('')}</div>${proofLinks(e.paymentProofs)}</div>`).join('')}${i.supportingFiles?.length?`<h3 class="drawer-section-title" style="margin-top:23px">补充附件</h3>${i.supportingFiles.map(f=>`<div class="review-expense"><div><strong>${escape(f.name)}</strong><small>${byteSize(f.size)}</small></div><a class="preview-link" href="/api/files/${encodeURIComponent(f.id)}" target="_blank" rel="noopener">查看${icon('external')}</a></div>`).join('')}`:''}${i.note?`<h3 class="drawer-section-title" style="margin-top:24px">嘉宾留言</h3><p style="font-size:12px;white-space:pre-wrap;color:#8c9a80">${escape(i.note)}</p>`:''}<div class="total-bar" style="margin-top:22px"><span>申请合计</span><strong class="money"><small>¥</small>${money(i.totalAmount)}</strong></div><div class="form-separator"></div>${i.deletedAt?`<div class="notice">${icon('info')}<div>此申请于 ${date(i.deletedAt)} 移入回收站。恢复后可继续审核。</div></div>`:`<h3 class="drawer-section-title">审核处理</h3><div class="field"><label for="review-status">处理状态</label><select id="review-status" name="review-status">${Object.entries(statusLabels).map(([k,v])=>`<option value="${k}" ${state.admin.reviewStatus===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="review-note">审核备注<span class="optional">嘉宾查询时可见</span></label><textarea id="review-note" name="review-note" maxlength="2000" placeholder="如需补充，请明确说明材料及联系方法">${escape(state.admin.reviewNote)}</textarea></div><div class="notice">${icon('info')}<div>更改状态只用于记录处理进度。“已打款”请在财务实际完成付款后标记。</div></div>`}</div><div class="drawer-footer">${i.deletedAt?`<button type="button" class="btn btn-ghost" data-action="close-drawer">关闭</button><button type="button" class="btn btn-primary" data-action="restore-submission" data-id="${escape(i.id)}" ${state.busy?'disabled':''}>${icon('back')}恢复申请</button>`:`<button type="button" class="btn btn-ghost danger-text" data-action="delete-submission" data-id="${escape(i.id)}" ${state.busy?'disabled':''}>删除申请</button><button type="button" class="btn btn-ghost" data-action="close-drawer">取消</button><button class="btn btn-primary" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':icon('check')}${state.busy?'正在保存…':'保存处理结果'}</button>`}</div></form></section></div>`}
function render(){document.body.dataset.view=state.view;root.innerHTML=header()+(state.view==='admin'?(state.admin.authenticated?dashboard():login()):state.view==='lookup'?lookup():guest());document.title=`${state.view==='admin'?'报销工作台':state.view==='lookup'?'进度查询':'嘉宾报销'} · ${state.config?.eventName||'零一万物2026西南生态大会'}`;document.body.style.overflow=state.admin.selected?'hidden':''}
function focusHeading(){requestAnimationFrame(()=>{const el=document.querySelector('.section-title,.page-title');if(el){el.setAttribute('tabindex','-1');el.focus({preventScroll:true})}window.scrollTo({top:0,behavior:'smooth'})})}
async function nextStep(){
 if(state.busy||hasPendingFiles())return;
 state.errors={};
 if(state.step===1){
  for(const key of ['name','mobile','organization'])state.applicant[key]=state.applicant[key].trim();
  if(!state.applicant.name)state.errors.name='请填写嘉宾姓名';
  if(!/^\+?[\d\s-]{6,20}$/.test(state.applicant.mobile))state.errors.mobile='请填写有效的联系手机';
  if(!state.applicant.organization)state.errors.organization='请填写所在单位或机构名称';
  if(!state.guestAuthenticated&&!state.inviteCode.trim())state.errors.inviteCode='请输入对接人提供的邀请码';
  validatePayment();draftStore.changed();
  if(Object.keys(state.errors).length){render();document.querySelector('.invalid input')?.focus();return}
  state.busy=true;render();
  try{
   if(!state.guestAuthenticated)await api('/api/guest/session',json('POST',{inviteCode:state.inviteCode.trim()}));
   state.guestAuthenticated=true;state.inviteCode='';state.step=2;
   if(!state.expenses.length)state.expenses.push(blankExpense());
   draftStore.changed(true);
  }catch(e){state.errors.inviteCode=e.message}
  finally{state.busy=false;render();focusHeading()}
  return;
 }
 if(state.step===2){
  if(!state.expenses.length)state.errors.expenses='请至少上传一份报销票据';
  state.expenses.forEach((e,i)=>{
   if(!e.fileId)state.errors[`expense-${i}-file`]='请上传本笔费用的票据';
   if(!e.category)state.errors[`expense-${i}-category`]='请选择费用类型';
   if(e.fileId&&(!Number.isFinite(Number(e.amount))||Number(e.amount)<=0||Number(e.amount)>100000))state.errors[`expense-${i}-amount`]='请填写有效的报销金额';
   for(const [key,label] of [['taxAmount','税额'],['netAmount','不含税金额']])if(e[key]!==''&&e[key]!=null&&(!Number.isFinite(Number(e[key]))||Number(e[key])<0||Number(e[key])>100000))state.errors[`expense-${i}-${key}`]='请核对'+label;
  });
  if(Object.keys(state.errors).length){render();document.querySelector('.invalid input')?.focus();return}
  state.step=3;draftStore.changed(true);render();focusHeading();return;
 }
 if(!state.consent){state.errors.consent='请确认资料使用说明后提交';render();return}
 state.busy=true;render();
 try{
  if(!await draftStore.flush())throw new Error('草稿尚未保存，请先重试保存后提交。');
  draftStore.suspend();
  const payload={applicant:state.applicant,payment:{...state.payment,bankName:state.payment.method==='bank'?state.payment.bankName:'',bankBranch:state.payment.method==='bank'?state.payment.bankBranch:''},expenses:state.expenses.map(e=>({...expenseSnapshot(e),amount:Number(e.amount),netAmount:e.netAmount==null||e.netAmount===''?'':Number(e.netAmount),taxAmount:e.taxAmount==null||e.taxAmount===''?'':Number(e.taxAmount)})),supportingFiles:state.supportingFiles.map(f=>f.fileId),note:state.note,consent:true};
  state.success=await api('/api/submissions',{...json('POST',payload),headers:{'Idempotency-Key':state.submissionKey}});
  draftStore.complete();
 }catch(e){state.errors.submit=e.message;draftStore.resume();handleGuestExpiry(e)}
 finally{state.busy=false;render();focusHeading()}
}

const uploadPreparations=new Set();
function fileCount(){return state.expenses.reduce((n,e)=>n+(e.fileId||e.uploading?1:0)+(e.paymentProofs?.length||0),0)+state.supportingFiles.length}
function hasPendingFiles(){return uploadPreparations.size>0||state.expenses.some(e=>e.uploading||e.recognizing||e.removing||e.paymentProofs?.some(p=>p.uploading||p.removing))||state.supportingFiles.some(e=>e.uploading||e.removing)}
function handleGuestExpiry(error){if(error.status===401){state.guestAuthenticated=false;state.step=1;state.errors.inviteCode='会话已过期，请重新输入邀请码，已填内容仍保留。';draftStore.changed(true)}}
function proofLinks(files=[]){return files.length?`<div class="proof-links"><strong>支付截图 · ${files.length} 张</strong>${files.map(f=>`<a class="preview-link" href="/api/files/${encodeURIComponent(f.id||f.fileId)}" target="_blank" rel="noopener">${icon('file')}${escape(f.name)}${icon('external')}</a>`).join('')}</div>`:''}
function paymentProofSection(e){
 const files=e.paymentProofs||[],id=`proof-input-${e.uid}`,disabled=e.removing||e.uploading||e.recognizing;
 return `<section class="payment-proof-section"><div class="proof-heading"><div><h4>支付截图<span class="optional">选填</span></h4><p>上传本笔费用对应的付款记录，便于财务核对。</p></div><span class="proof-count">${files.length} / 3</span></div><div class="proof-list">${files.map(f=>`<div class="proof-file">${f.uploading?'<span class="spinner"></span>':state.guestAuthenticated?`<a href="/api/files/${encodeURIComponent(f.fileId)}" target="_blank" rel="noopener"><img src="/api/files/${encodeURIComponent(f.fileId)}" alt="支付截图预览" loading="lazy"/></a>`:icon('file')}<div><strong>${escape(f.name)}</strong><small>${f.uploading?'正在上传…':byteSize(f.size)}</small></div><button class="icon-button" type="button" data-action="remove-proof" data-id="${e.uid}" data-proof="${f.uid}" aria-label="移除支付截图 ${escape(f.name)}" ${f.uploading||f.removing||disabled?'disabled':''}>${icon('close')}</button></div>`).join('')}</div>${files.length<3?`<label class="proof-upload ${disabled?'disabled':''}" for="${id}">${icon('upload')}添加支付截图<input class="visually-hidden" id="${id}" type="file" accept="image/jpeg,image/png" multiple data-upload="payment-proof" data-target="${e.uid}" ${disabled?'disabled':''}/></label><p class="field-hint">支持 JPG、PNG，每笔最多 3 张，不计入报销金额。</p>`:''}</section>`;
}
async function uploadFiles(files,purpose='invoice',targetUid=''){
 if(!files?.length||state.busy)return;
 const support=purpose==='support',proof=purpose==='payment-proof',parent=state.expenses.find(e=>e.uid===targetUid),lockKey=support?'support':targetUid;
 if(uploadPreparations.has(lockKey))return;
 if(!support&&(!parent||parent.removing||parent.uploading||parent.recognizing))return;
 if(!support&&!proof&&files.length>1){toast('每笔费用请上传一张票据，其他票据请新增费用',true);return}
 if(proof&&(parent.paymentProofs.length+files.length>3)){toast('每笔费用最多上传 3 张支付截图',true);return}
 if(fileCount()+files.length>(state.config.maxFiles||12)){toast(`每份申请最多 ${state.config.maxFiles||12} 个文件（含支付截图和补充附件）`,true);return}
 // Persist the expense uid before uploading so a completed request can be recovered after closing.
 uploadPreparations.add(lockKey);render();
 try{
 draftStore.changed();if(!await draftStore.flush()){toast('请先恢复草稿保存，再上传文件。',true);return}
 if(state.busy||(!support&&(!state.expenses.includes(parent)||parent.removing||parent.uploading||parent.recognizing)))return;
 for(const f of files){
  if(proof&&parent.paymentProofs.length>=3){toast('每笔费用最多上传 3 张支付截图',true);break}
  if(!(proof?['image/jpeg','image/png']:['image/jpeg','image/png','application/pdf']).includes(f.type)){toast(`${f.name}：${proof?'支付截图请上传 JPG 或 PNG':'请上传 PDF、JPG 或 PNG 文件'}`,true);continue}
  if(f.size>state.config.maxFileSize||!f.size){toast(`${f.name}：文件为空或超过大小限制`,true);continue}
  if(fileCount()>=(state.config.maxFiles||12)){toast('已达到文件数量上限',true);break}
  const list=support?state.supportingFiles:proof?parent.paymentProofs:state.expenses;
  const item=support||proof?{uid:crypto.randomUUID()}:parent;
  if(!support&&!proof&&item.fileId)continue;
  Object.assign(item,{name:f.name,size:f.size,mime:f.type,uploading:true});if(support||proof)list.push(item);render();
  try{
   const r=await api('/api/uploads',{method:'POST',headers:{'Content-Type':f.type,'X-Filename':encodeURIComponent(f.name),'X-Upload-Purpose':purpose,...(!support?{'X-Draft-Entry':parent.uid}:{})},body:f});
   Object.assign(item,{fileId:r.id,name:r.name||f.name,size:r.size||f.size,mime:r.mime||f.type,uploading:false,...(!support&&!proof?{ocr:r.ocr,...r.ocr?.fields}:{})});
   if(!support&&!proof){applyOcrCategory(item);delete state.errors.expenses;delete state.errors[`expense-${state.expenses.indexOf(item)}-file`];if(r.ocr?.status==='done')toast('已提取本笔票据信息，请核对金额和字段')}
  }catch(e){
   if(support||proof){const idx=list.indexOf(item);if(idx>=0)list.splice(idx,1)}else Object.assign(item,{uploading:false,name:'',size:0,mime:''});
   toast(e.message,true);handleGuestExpiry(e);
  }
  draftStore.changed(true);render();
 }
 }finally{uploadPreparations.delete(lockKey);render()}
}
async function deleteUploaded(item){if(item.fileId)await api(`/api/uploads/${encodeURIComponent(item.fileId)}`,{method:'DELETE'})}
async function removeExpense(uid,onlyFile=false){
 const e=state.expenses.find(e=>e.uid===uid);if(!e||uploadPreparations.has(uid)||e.uploading||e.recognizing||e.removing||e.paymentProofs.some(p=>p.uploading||p.removing))return;
 e.removing=true;render();
 try{
  if(!onlyFile)for(const proof of [...e.paymentProofs]){await deleteUploaded(proof);e.paymentProofs.splice(e.paymentProofs.indexOf(proof),1);draftStore.changed(true)}
  await deleteUploaded(e);
  const index=state.expenses.findIndex(item=>item.uid===uid);if(index<0)return;
  if(onlyFile){const replacement=blankExpense();Object.assign(e,replacement,{uid,category:e.category,note:e.note,paymentProofs:e.paymentProofs,removing:false})}else state.expenses.splice(index,1);
  state.errors={};draftStore.changed(true);
 }catch(error){toast(error.message,true);handleGuestExpiry(error)}finally{e.removing=false;render()}
}
async function removeSupportingFile(uid){
 const e=state.supportingFiles.find(e=>e.uid===uid);if(!e||e.uploading||e.removing)return;
 e.removing=true;render();
 try{await deleteUploaded(e);const index=state.supportingFiles.findIndex(item=>item.uid===uid);if(index>=0)state.supportingFiles.splice(index,1);draftStore.changed(true)}
 catch(error){toast(error.message,true);handleGuestExpiry(error)}finally{e.removing=false;render()}
}
async function removePaymentProof(uid,proofUid){
 const e=state.expenses.find(e=>e.uid===uid),proof=e?.paymentProofs.find(f=>f.uid===proofUid);if(!proof||uploadPreparations.has(uid)||proof.uploading||proof.removing||e.removing)return;
 proof.removing=true;render();
 try{await deleteUploaded(proof);e.paymentProofs.splice(e.paymentProofs.indexOf(proof),1);draftStore.changed(true)}
 catch(error){toast(error.message,true);handleGuestExpiry(error)}finally{proof.removing=false;render()}
}

async function recognizeAgain(uid){
 const e=state.expenses.find(e=>e.uid===uid);if(!e||uploadPreparations.has(uid)||e.uploading||e.recognizing||e.removing||!e.fileId)return;
 const previousFields=e.ocr?.fields||{};
 const manualFields=new Set(['invoiceNumber','date','buyerName','buyerTaxId','sellerName','sellerTaxId','netAmount','taxAmount','amount'].filter(key=>String(e[key]??'')!==String(previousFields[key]??'')));
 e.recognizing=true;render();
 try{
  const r=await api(`/api/uploads/${encodeURIComponent(e.fileId)}/recognize`,json('POST',{}));
  e.ocr=r.ocr;applyOcrCategory(e);
  let updated=0;
  for(const [key,value] of Object.entries(r.ocr?.fields||{}))if(value!==''&&value!=null&&!manualFields.has(key)){e[key]=value;updated++}
  const count=Object.values(r.ocr?.fields||{}).filter(v=>v!==''&&v!=null).length;
  toast(count?`已更新 ${updated} 项，保留手动修改，请核对`:'未提取到有效字段，请手动填写',!count);
 }catch(error){toast(error.message,true)}finally{e.recognizing=false;draftStore.changed(true);render()}
}

let adminLoadSequence=0;
async function loadAdmin(){
 const a=state.admin,sequence=++adminLoadSequence;a.loading=true;a.error='';render();
 try{const r=await api('/api/admin/submissions'+(a.showTrash?'?deleted=1':''));if(sequence!==adminLoadSequence)return;a.items=r.items||[];a.trashCount=r.trashCount||0;a.authenticated=true}
 catch(e){if(sequence===adminLoadSequence){a.error=e.message;if(e.status===401)a.authenticated=false}}
 finally{if(sequence===adminLoadSequence){a.loading=false;render()}}
}
async function changeSubmissionDeletion(id,restore=false){
 const a=state.admin,item=a.items.find(i=>String(i.id)===String(id));
 if(!item||state.busy||a.loading)return false;
 if(!restore&&!window.confirm(`确定删除这份申请并移入回收站？\n嘉宾：${item.applicant?.name||''}\n手机号：${item.applicant?.mobile||''}\n申请编号：${item.reference}\n金额：¥ ${money(item.totalAmount)}\n\n删除后不计入统计、导出与嘉宾查询，可在回收站恢复。`))return false;
 state.busy=true;render();
 try{
  await api(`/api/admin/submissions/${encodeURIComponent(id)}${restore?'/restore':''}`,json(restore?'POST':'DELETE',{}));
  a.items=a.items.filter(i=>String(i.id)!==String(id));a.trashCount=Math.max(0,a.trashCount+(restore?-1:1));a.selected=null;
  toast(restore?'申请已恢复':'申请已移入回收站');await loadAdmin();return true;
 }catch(e){toast(e.message,true);if(e.status===401)a.authenticated=false;return false}
 finally{state.busy=false;render()}
}

async function loginSubmit(){if(state.busy)return;state.busy=true;state.admin.error='';render();try{await api('/api/admin/login',json('POST',{password:state.admin.password}));state.admin.password='';state.admin.authenticated=true;await loadAdmin()}catch(e){state.admin.error=e.message}finally{state.busy=false;render()}}
async function lookupSubmit(){const l=state.lookup;if(l.busy)return;l.busy=true;l.error='';l.result=null;render();try{l.result=await api('/api/guest/lookup',json('POST',{mobile:l.mobile.trim()}))}catch(e){l.error=e.message}finally{l.busy=false;render()}}
async function reviewSubmit(){if(state.busy||state.admin.items.find(i=>i.id===state.admin.selected)?.deletedAt)return;if(state.admin.reviewStatus==='needs_info'&&!state.admin.reviewNote.trim()){toast('请填写需要补充的材料，方便嘉宾处理',true);return}state.busy=true;render();try{await api(`/api/admin/submissions/${encodeURIComponent(state.admin.selected)}`,json('PATCH',{status:state.admin.reviewStatus,reviewNote:state.admin.reviewNote}));state.admin.selected=null;toast('处理结果已保存');await loadAdmin()}catch(e){toast(e.message,true)}finally{state.busy=false;render()}}
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message)}catch{window.prompt('请复制以下内容',text)}}
const invoiceKeys=['category','amount','invoiceNumber','date','buyerName','buyerTaxId','sellerName','sellerTaxId','netAmount','taxAmount','note'];
function expenseSnapshot(e){return Object.fromEntries([['uid',e.uid],['fileId',e.fileId||''],...invoiceKeys.map(key=>[key,e[key]??'']),['paymentProofIds',(e.paymentProofs||[]).filter(f=>f.fileId).map(f=>f.fileId)]])}
function draftSnapshot(){return {version:1,step:state.step,applicant:{...state.applicant},payment:{...state.payment},expenses:state.expenses.map(expenseSnapshot),supportingFiles:state.supportingFiles.filter(f=>f.fileId).map(f=>f.fileId),note:state.note,submissionKey:state.submissionKey}}
function restoreDraft(data){
 state.guestAuthenticated=!!data.authenticated;
 const draft=data.draft;if(!draft)return;
 for(const key of Object.keys(state.applicant))state.applicant[key]=draft.applicant?.[key]||'';
 for(const key of Object.keys(state.payment))state.payment[key]=draft.payment?.[key]||(key==='method'?'bank':'');
 state.note=draft.note||'';state.step=Math.min(3,Math.max(1,Number(draft.step)||1));state.submissionKey=draft.submissionKey||crypto.randomUUID();state.consent=false;state.inviteCode='';
 const uploads=data.uploads||[],byId=new Map(uploads.map(f=>[f.id,f])),used=new Set();
 const attach=f=>{used.add(f.id);return {uid:crypto.randomUUID(),fileId:f.id,name:f.name,size:f.size,mime:f.mime,uploading:false}};
 state.expenses=(draft.expenses||[]).map(saved=>{
  const e={...blankExpense(),uid:saved.uid};for(const key of invoiceKeys)e[key]=saved[key]??'';
  const file=byId.get(saved.fileId)||uploads.find(f=>f.purpose==='invoice'&&f.clientRef===e.uid&&!used.has(f.id));
  if(file){Object.assign(e,attach(file),{uid:saved.uid,ocr:file.ocr});if(!saved.fileId){applyOcrCategory(e);for(const [key,value] of Object.entries(file.ocr?.fields||{}))if(e[key]===''||e[key]==null)e[key]=value}}
  const proofIds=new Set(saved.paymentProofIds||[]);
  e.paymentProofs=uploads.filter(f=>f.purpose==='payment-proof'&&(proofIds.has(f.id)||f.clientRef===e.uid)).slice(0,3).map(attach);
  return e;
 });
 state.supportingFiles=uploads.filter(f=>(draft.supportingFiles||[]).includes(f.id)||f.purpose==='support').filter(f=>!used.has(f.id)).map(attach);
 if(!state.guestAuthenticated&&state.step>1){state.step=1;state.errors.inviteCode='请重新验证邀请码后继续，已填内容和已上传文件已恢复。'}
}
function draftStatusHtml(){
 const d=state.draftStatus,copy={loading:'正在恢复草稿…',ready:'填写后自动保存草稿',waiting:'有修改，等待保存…',saving:'正在保存草稿…',saved:`草稿已保存${d.lastSaved?' · '+date(d.lastSaved):''}`,restored:`已恢复上次草稿${d.lastSaved?' · '+date(d.lastSaved):''}`,error:d.message||'草稿保存失败，请重试',conflict:d.message||'另一页面更新了草稿，请重新载入',submitted:'已提交'};
 return `<div class="draft-status ${d.phase==='error'||d.phase==='conflict'?'draft-error':''}" id="draft-status" role="status" aria-live="polite"><div>${icon(['saving','waiting','loading'].includes(d.phase)?'clock':d.phase==='error'||d.phase==='conflict'?'info':'check')}<span>${escape(copy[d.phase]||copy.ready)}<small>同一浏览器可恢复，草稿保留 30 天；上传完成后再退出。</small></span></div>${d.phase==='error'?'<button class="text-button" type="button" data-action="draft-retry">重试保存</button>':d.phase==='conflict'?'<button class="text-button" type="button" data-action="reload">重新载入</button>':''}</div>`;
}
const draftStore=createDraftStore({api,snapshot:draftSnapshot,restore:restoreDraft,onStatus:value=>{state.draftStatus=value;if(value.phase==='submitted'&&!state.success){state.success={totalAmount:total(),expenseCount:state.expenses.length,submittedAt:''};render();return}const el=document.querySelector('#draft-status');if(el)el.outerHTML=draftStatusHtml()}});
function saveOnExit(){if(state.view!=='admin'&&!state.success)draftStore.beacon((url,body)=>navigator.sendBeacon(url,new Blob([body],{type:'application/json'})))}
window.addEventListener('pagehide',saveOnExit);
window.addEventListener('online',()=>{if(state.view!=='admin')void draftStore.retry()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveOnExit();else if(state.view!=='admin'&&!state.success)void draftStore.flush()});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='guest-form')nextStep();if(e.target.id==='login-form')loginSubmit();if(e.target.id==='lookup-form')lookupSubmit();if(e.target.id==='review-form')reviewSubmit()});
function clearFieldError(el){let key=el.id;if(el.dataset.expense){const index=state.expenses.findIndex(e=>e.uid===el.dataset.expense);key=`expense-${index}-${el.dataset.key}`}delete state.errors[key];const field=el.closest('.field');field?.classList.remove('invalid');field?.querySelector('.field-error')?.remove()}
root.addEventListener('input',e=>{const el=e.target,n=el.name;clearFieldError(el);if(Object.hasOwn(state.applicant,n))state.applicant[n]=el.value;else if(n.startsWith('payment-')&&n!=='payment-method')state.payment[n.slice(8)]=el.value;else if(n==='inviteCode')state.inviteCode=el.value;else if(n==='note')state.note=el.value;else if(n==='consent')state.consent=el.checked;else if(n==='admin-password')state.admin.password=el.value;else if(n==='lookup-mobile')state.lookup.mobile=el.value;else if(n==='review-status')state.admin.reviewStatus=el.value;else if(n==='review-note')state.admin.reviewNote=el.value;if(el.dataset.expense){const item=state.expenses.find(e=>e.uid===el.dataset.expense);if(item)item[el.dataset.key]=el.value;const marker=el.closest('.field')?.querySelector('.auto-tag');if(marker&&String(item?.ocr?.fields?.[el.dataset.key])!==String(el.value))marker.remove();refreshExpenseTotals()}if(Object.hasOwn(state.applicant,n)||n.startsWith('payment-')||n==='note'||el.dataset.expense)draftStore.changed();if(el.id==='admin-search'){state.admin.query=el.value;document.querySelector('#admin-table').innerHTML=adminTable();document.querySelectorAll('a[href*="/api/admin/export."]').forEach(a=>a.href=exportUrl(a.href.includes('.xlsx')?'xlsx':'zip'))}});
root.addEventListener('change',e=>{if(e.target.dataset.upload)uploadFiles([...e.target.files],e.target.dataset.upload==='expense'?'invoice':e.target.dataset.upload,e.target.dataset.target);if(e.target.dataset.expense){const item=state.expenses.find(i=>i.uid===e.target.dataset.expense);if(item)item[e.target.dataset.key]=e.target.value;refreshExpenseTotals();draftStore.changed();if(e.target.dataset.key==='category'){const zone=e.target.closest('.expense-card')?.querySelector('.expense-upload');if(zone){zone.querySelector('.ticket-upload-hint')?.remove();zone.insertAdjacentHTML('beforeend',ticketUploadHint(item.category))}}}if(e.target.name==='payment-method'){state.payment.method=e.target.value;state.payment.accountNumber='';if(!state.payment.accountName)state.payment.accountName=state.applicant.name.trim();state.errors={};draftStore.changed();render()}if(e.target.name==='review-status')state.admin.reviewStatus=e.target.value;if(e.target.name==='consent')state.consent=e.target.checked});
root.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='close-drawer'&&el.id==='review-overlay'&&e.target!==el)return;if(action==='reload'){location.reload();return}if(action==='draft-retry'){await draftStore.retry();return}if(action==='guest'){if(state.view==='admin'){location.href='/';return}state.view='guest';render()}else if(action==='lookup'||action==='lookup-success'){if(state.success){state.lookup.mobile=state.applicant.mobile}state.view='lookup';state.admin.selected=null;render();focusHeading()}else if(action==='previous'){state.step=Math.max(1,state.step-1);state.errors={};draftStore.changed(true);render();focusHeading()}else if(action==='step'){state.step=Number(el.dataset.step);state.errors={};draftStore.changed(true);render();focusHeading()}else if(action==='add-expense'){if(state.expenses.length>=(state.config?.maxFiles||12)||fileCount()>=(state.config?.maxFiles||12)){toast('已达到本份申请的文件数量上限',true);return}const entry=blankExpense();state.expenses.push(entry);draftStore.changed(true);render();document.querySelector(`#category-${state.expenses.length-1}`)?.focus()}else if(action==='remove-proof')removePaymentProof(el.dataset.id,el.dataset.proof);else if(action==='remove-expense')removeExpense(el.dataset.id);else if(action==='recognize')recognizeAgain(el.dataset.id);else if(action==='remove-file'){if(el.dataset.support==='true')removeSupportingFile(el.dataset.id);else removeExpense(el.dataset.id,true)}else if(action==='copy-link')copy(location.origin+'/','嘉宾提交地址已复制');else if(action==='delete-submission')await changeSubmissionDeletion(el.dataset.id);else if(action==='restore-submission')await changeSubmissionDeletion(el.dataset.id,true);else if(action==='toggle-trash'){if(state.busy||state.admin.loading)return;state.admin.showTrash=!state.admin.showTrash;state.admin.filter='all';state.admin.query='';state.admin.selected=null;state.admin.items=[];await loadAdmin()}else if(action==='filter'){state.admin.filter=el.dataset.filter;render()}else if(action==='refresh')loadAdmin();else if(action==='logout'){try{await api('/api/admin/logout',json('POST',{}));adminLoadSequence++;state.admin.authenticated=false;state.admin.loading=false;state.admin.items=[];state.admin.showTrash=false;state.admin.trashCount=0;state.admin.selected=null;render()}catch(e){toast(e.message,true)}}else if(action==='review'){state.admin.selected=el.dataset.id;const item=state.admin.items.find(i=>String(i.id)===String(el.dataset.id));state.admin.reviewStatus=item.status;state.admin.reviewNote=item.reviewNote||'';render();requestAnimationFrame(()=>document.querySelector('#drawer-title')?.focus())}else if(action==='close-drawer'){state.admin.selected=null;render()}});
root.addEventListener('dragover',e=>{const zone=e.target.closest('[data-dropzone]');if(zone){e.preventDefault();zone.classList.add('dragging')}});
root.addEventListener('dragleave',e=>e.target.closest('[data-dropzone]')?.classList.remove('dragging'));
root.addEventListener('drop',e=>{const zone=e.target.closest('[data-dropzone]');if(zone){e.preventDefault();zone.classList.remove('dragging');uploadFiles([...e.dataTransfer.files],zone.dataset.dropzone==='support'?'support':'invoice',zone.dataset.target)}});
root.addEventListener('keydown',e=>{if(e.target.matches('[data-dropzone]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();document.getElementById(e.target.htmlFor)?.click()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.admin.selected){state.admin.selected=null;render()}if(e.key==='Tab'&&state.admin.selected){const nodes=[...document.querySelectorAll('.drawer a,.drawer button,.drawer select,.drawer textarea')].filter(el=>!el.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
async function init(){try{state.config=await api('/api/config');if(state.view==='admin'){try{const r=await api('/api/admin/session');state.admin.authenticated=!!r.authenticated;if(state.admin.authenticated){const data=await api('/api/admin/submissions');state.admin.items=data.items||[];state.admin.trashCount=data.trashCount||0}}catch{state.admin.authenticated=false}}else await draftStore.initialize();render()}catch(e){root.innerHTML=`<main class="page"><div class="main-card"><div class="success-body"><div class="success-mark">${icon('info')}</div><h2>服务暂时无法连接</h2><p>请从已启动的网站地址访问；直接打开 HTML 文件无法提交资料。</p><button class="btn btn-primary" data-action="reload">重新连接</button></div></div></main>`;toast(e.message,true)}}
